with valid as (select *, lower(region) as region_lower, last_day(opened_date) as opened_date_month_end, coalesce(region, 'OTHER') as region_clean from stores where opened_date > date '2023-03-30' and city = 'Singapore'), with_windows as (select *, lag(sqft) over w_running as prev_sqft, lead(sqft) over w_running as next_sqft, row_number() over w_running as row_seq, row_number() over w_hist as event_seq from valid where region != 'Central' window w_running as (partition by region, city order by opened_date_month_end, id), w_hist as (partition by region order by opened_date_month_end, id)), kept as (select s.* from with_windows s where exists (select 1 from inventory x where x.store_id = s.id and x.store_id in (1, 2, 3, 4))), enriched as (select *, avg(next_sqft) over (order by row_seq, id rows between 3 preceding and 1 preceding) as next_sqft_avg_3_prior, lag(prev_sqft, 2, 0) over (partition by city order by event_seq, id) as prev_prev_sqft from kept) select id, store_name, opened_date, sqft, region_lower, opened_date_month_end, region_clean, next_sqft, prev_prev_sqft from enriched order by prev_prev_sqft;
